"""Separate overdue reminders (#221): the single ``reminder_note`` becomes a
note per kind (missed pickup / missed return) — the old text is copied into
both — plus schedules, a per-pool notice switch and a per-product setting."""

import django.core.validators
from django.db import migrations, models


NOTE_SUFFIXES = ("", "_de", "_en")


def copy_reminder_note(apps, schema_editor):
    NotificationSetting = apps.get_model("catalog", "NotificationSetting")
    for setting in NotificationSetting.objects.all():
        for suffix in NOTE_SUFFIXES:
            value = getattr(setting, f"reminder_note{suffix}")
            setattr(setting, f"overdue_pickup_note{suffix}", value)
            setattr(setting, f"overdue_return_note{suffix}", value)
        setting.save()


def restore_reminder_note(apps, schema_editor):
    """Best effort: the return note (else the pickup note) becomes the
    single reminder note again."""
    NotificationSetting = apps.get_model("catalog", "NotificationSetting")
    for setting in NotificationSetting.objects.all():
        for suffix in NOTE_SUFFIXES:
            value = getattr(setting, f"overdue_return_note{suffix}") or getattr(
                setting, f"overdue_pickup_note{suffix}"
            )
            if suffix == "":
                value = value or ""
            setattr(setting, f"reminder_note{suffix}", value)
        setting.save()


